    >>> from pkg import mod1, mod2
    >>> from astropy.utils import find_current_module
    >>> mod1.find1()
    pkg.mod1
    >>> mod1.find2()
    None
    >>> mod2.find()
    pkg.mod2
    >>> find_current_module(0)
    <module 'astropy.utils.misc' from 'astropy/utils/misc.py'>
    >>> mod1.find_diff()
    pkg.mod1

"""

frm = inspect.currentframe()
for i in range(depth):
    frm = frm.f_back
    if frm is None:
        return None

if finddiff:
    currmod = inspect.getmodule(frm)
    if finddiff is True:
        diffmods = [currmod]
    else:
        diffmods = []
        for fd in finddiff:
            if inspect.ismodule(fd):
                diffmods.append(fd)
            elif isinstance(fd, str):
                diffmods.append(importlib.import_module(fd))
            elif fd is True:
                diffmods.append(currmod)
            else:
                raise ValueError('invalid entry in finddiff')

    while frm:
        frmb = frm.f_back
        modb = inspect.getmodule(frmb)
        if modb not in diffmods:
            return modb
        frm = frmb
else:
    return inspect.getmodule(frm)

