                         'latargs': {'unit': u.degree, 'pad': True, 'alwayssign': True}},
              'dms': {'lonargs': {'unit': u.degree},
                      'latargs': {'unit': u.degree}},
              'decimal': {'lonargs': {'unit': u.degree, 'decimal': True},
                          'latargs': {'unit': u.degree, 'decimal': True}}
              }

